MODULE HumanValues

// CONV: INTERPRET/INFER=reader semantic work. RECORD=attributed, unverified. REQUIRE/ASSERT=specified, not run. EXPECT=reproducible target, not theorem. Bindings+matrix=inherited single-encoder annotations; use layer+guards=proposals.



// USE

