Horizon{pr:present ls:lifespan ig:intergenerational cs:cosmic at:atemporal}

Authority{rev:revelation rsn:reason emp:empirical_nature vex:verified_experience trd:tradition com:community ind:individual_will non:none} // warrant annotation, not ACL

SourceType{pt:primary_text cc:canonical_compilation ic:institutional_credo ar:analytic_reconstruction es:ethnographic_synthesis}

Loss{lo me hi} Franchise{full advisory draft control meta} Revision{revisable bounded fixed unknown} Grade{c:concede p:partial h:hold}

Verdict{E:endorsed P:permitted T:reading-dependent(≥1 E/P & ≥1 F reading) F:forbidden U:insufficient_evidence} // U≠P/T; T=readings judged to exist, not certified

Assessment{STRICT_PASS WEAK_ONLY BLOCKED INSUFFICIENT_EVIDENCE NO_RELEVANT_FRAMEWORKS OUTSIDE_RESEARCH_SCOPE}

Probability:=exact[0,1] Many<T>:=T|Set<T> AS_SET(x):=x is Set?x:{x}

Reading{id:=(A,c,rN),label,anchors,verdict,verified:=false} Component{id,name,statement,basis,order,role} Alternative{label,subject,authority,cites}

